static double uiNow(){return std::chrono::duration<double>(std::chrono::steady_clock::now().time_since_epoch()).count();}
static void heading(const char*s,ImFont*f){if(f)ImGui::PushFont(f);ImGui::TextUnformatted(s);if(f)ImGui::PopFont();}
static void wrapped(const std::string&s){ImGui::TextWrapped("%s",s.c_str());}
static int findColumn(const Table&t,std::initializer_list<const char*> names){for(auto n:names){int c=t.column(n);if(c>=0)return c;}return -1;}
void App::updateDocument(){if(auto*t=selected()){auto&d=documents_[document_];d.graph=enrichSit(*t);d.x=-2;d.y=findColumn(d.graph,{"T","T_degF"});selectionFirst_=1;selectionLast_=int(t->rows.size());zooms_.clear();int j=0;for(size_t i=0;i<d.graph.columns.size()&&j<10;i++)if(d.graph.columns[i]!="COUNT"&&d.graph.columns[i]!="SERIES"&&std::isfinite(statistics(d.graph,int(i)).mean)){multiColumns_[j]=int(i);multiActive_[j]=j<4;j++;}}}
void App::openMeasurements(bool convert){if(loading_)return;auto p=fileDialog(false,convert?L"Convert measurements":L"Open measurements",L"txt",L"SAIV measurements\0*.SD2;*.txt;*.csv;*.log;*.asc;*.SF2\0All files\0*.*\0\0");if(!p.empty()){convertAfterLoad_=convert;loadFile(p);}}
void App::beginDetect(){if(settingBusy_||detector_.busy)return;disconnect();detectionSelection_=-1;detector_.start();dialog_="Autodetect";error_.clear();page_=1;}
void App::beginDownload(){downloadHandled_=false;error_.clear();if(!serial_.connected){error_="Use Autodetect or Connect before downloading.";return;}if(protocol_.mainMenu||protocol_.device.logger)protocol_.receiveData(uiNow());else if(protocol_.wake(uiNow()))downloadWanted_=true;}
void App::saveTerminal(){std::string s;for(auto&line:terminal_){if(!showRawTraffic_&&line.size()>17&&line.substr(14,3)=="RX ")s+=line.substr(18);else s+=line;s+="\r\n";}s+=terminalPartial_;saveData(s,L"Save terminal text",L"txt");}
void App::saveMeasurements(){if(auto*t=selected())saveData(t->csv(),L"Save measurements as CSV",L"csv");}
void App::showData(int view,int pair,bool profile){if(!selected()){openMeasurements();return;}page_=2;dataView_=view;graphPair_=pair;documents_[document_].profile=profile;zooms_.clear();}
void App::openUtility(int type,const std::string&){utility_=type;preview_.reset();page_=3;}
void App::selectRange(){selectionFirst_=1;selectionLast_=selected()?int(selected()->rows.size()):1;dialog_="Select measurements";}
void App::applySetting(bool clock){if(!acceptedInstrument_||!serial_.connected||settingBusy_)return;fs::path config;if(!clock&&acceptedIdentity_.surface){config=fileDialog(false,L"Select config/system.ini on the connected Surface logger",L"ini",L"Surface configuration\0system.ini\0\0");if(config.empty())return;}settingBusy_=true;auto settings=settings_;auto identity=acceptedIdentity_;std::string context;for(auto&s:terminal_)context+=s+"\n";context+=terminalPartial_;int interval=intervalIndex_;bool utc=clockZone_==1;settingFuture_=std::async(std::launch::async,[this,settings,identity,context,clock,interval,utc,config]{return changeDeviceSetting(serial_,settings,identity,context,clock,interval,utc,config);});}
