 const char*names[]={"Temperature + Salinity","Temperature + Conductivity","Sound velocity + Density","Oxygen + Temperature","Fluorescence + Turbidity"};ImGui::SetNextItemWidth(280);if(ImGui::Combo("##pair",&graphPair_,names,5))zooms_.clear();ImGui::SameLine();ImGui::Checkbox("Show points",&showPoints_);ImGui::SameLine();ImGui::TextDisabled("Wheel to zoom; double-click to reset");
 int first=-1,second=-1;auto&g=d.graph;if(graphPair_==0||graphPair_==1){first=findColumn(g,{"T","T_degF"});second=graphPair_==0?findColumn(g,{"S","S_from_C","Salinity_SIT"}):g.column("C");}if(graphPair_==2){first=findColumn(g,{"c","Sound_velocity_SIT_m_s"});second=g.column("Density_anomaly_SIT_kg_m3");}if(graphPair_==3){first=findColumn(g,{"OX","OxR","OX_mg_L","OxR_mg_L"});second=findColumn(g,{"T","T_degF"});}if(graphPair_==4){first=g.column("OF");second=g.column("OT");}int axis=d.profile?findColumn(g,{"Depth_m","P"}):-2;
