 if(started){std::string text;if(page_==1){for(auto&s:terminal_)text+=s+"\n";text+=terminalPartial_;}else if(selected())text=selected()->csv();else text="SAIV Instrument Studio";int dpi=GetDeviceCaps(dc,LOGPIXELSY),margin=dpi/3,height=GetDeviceCaps(dc,VERTRES),width=GetDeviceCaps(dc,HORZRES);HFONT font=CreateFontW(-MulDiv(9,dpi,72),0,0,0,FW_NORMAL,FALSE,FALSE,FALSE,DEFAULT_CHARSET,OUT_DEFAULT_PRECIS,CLIP_DEFAULT_PRECIS,DEFAULT_QUALITY,FIXED_PITCH,L"Consolas");auto old=SelectObject(dc,font);TEXTMETRICW metrics;GetTextMetricsW(dc,&metrics);int lineHeight=metrics.tmHeight+metrics.tmExternalLeading,maxChars=std::max(1L,(width-2*margin)/std::max(1L,metrics.tmAveCharWidth));std::istringstream in(text);std::string line;int y=height;bool pageOpen=false;while(ok&&std::getline(in,line)){if(line.empty())line=" ";int count=MultiByteToWideChar(CP_UTF8,0,line.data(),int(line.size()),nullptr,0);std::wstring wide(count,L' ');MultiByteToWideChar(CP_UTF8,0,line.data(),int(line.size()),wide.data(),count);for(size_t p=0;ok&&p<wide.size();p+=maxChars){if(y+lineHeight>height-margin){if(pageOpen)ok=EndPage(dc)>0;if(ok)ok=StartPage(dc)>0;pageOpen=ok;y=margin;}if(ok)ok=TextOutW(dc,margin,y,wide.data()+p,int(std::min<size_t>(maxChars,wide.size()-p)))!=0;y+=lineHeight;}}if(pageOpen&&ok)ok=EndPage(dc)>0;SelectObject(dc,old);DeleteObject(font);if(ok)ok=EndDoc(dc)>0;else AbortDoc(dc);}if(dc)DeleteDC(dc);if(pd.hDevMode)GlobalFree(pd.hDevMode);if(pd.hDevNames)GlobalFree(pd.hDevNames);if(!ok)error_="Printing failed or was cancelled by the printer.";else notice_="Sent to printer.";
